head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.contnId;
scwin.notiObjSysCode;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로드 시 호출되는 진입점(현재 초기화 처리 없음).
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시 호출되는 핸들러(현재 처리 없음).
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_noticeList_OnLoadCompleted
 * @description 도움말 목록(dts_noticeList) 조회 완료 콜백(현재 처리 없음).
 * @param {Object} e 서브미션 완료 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dts_noticeList_OnLoadCompleted = function(e) {

};

/**
 * @method
 * @name MxGrid_2_OnDblClick
 * @description 도움말 목록 그리드 더블클릭 핸들러 — 화면ID·화면명 컬럼이면 선택 행의 화면ID를 보관 후 도움말 상세 팝업(ULDMGT42045)을 열고 재조회하며, 도움말 파일 컬럼이면 해당 도움말 파일을 다운로드한다.
 * @param {Number} row 더블클릭한 행 인덱스
 * @param {String} colid 더블클릭한 컬럼 ID
 * @returns {void}
 * @hidden N
 */
scwin.MxGrid_2_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'SCREN_ID' || colid === 'MENU_NM') {
            scwin.contnId = dts_noticeList.getCellData(row, "SCREN_ID");

            const options = {
                id: "ULDMGT42045",
                title: "도움말 상세",
                type: "browserPopup",
                width: "660px",
                height: "290px"
            };

            $c.win.openPopup("ULDMGT42045.gfm", options); // 대상 팝업은 반환값 없음(콜백 불요)
            scwin.listSync();
        } else if (colid === 'SAVE_FILE_NM') {
            const screnId = dts_noticeList.getCellData(row, "SCREN_ID");
            location.href = "/scren.do?method=downloadHelpFile&V_SCREN_ID=" + screnId;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT42040.MxGrid_2_OnDblClick" });
    }
};

/**
 * @method
 * @name bnt_Select_onclick
 * @description [조회] 버튼 클릭 시 도움말 목록을 조회(listSync)한다.
 * @param {Object} e 클릭 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.bnt_Select_onclick = function(e) {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42040.bnt_Select_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description [신규] 버튼 클릭 시 contnId를 "input"(신규 상태)으로 설정하고 도움말 상세 팝업(ULDMGT42045)을 연 뒤 목록을 재조회한다.
 * @param {Object} e 클릭 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = async function(e) {
    try {
        scwin.contnId = "input";

        const options = {
            id: "ULDMGT42045",
            title: "도움말 상세",
            type: "browserPopup",
            width: "660px",
            height: "290px"
        };

        $c.win.openPopup("ULDMGT42045.gfm", options); // 대상 팝업은 반환값 없음(콜백 불요)
        scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT42040.btn_New_onclick" });
    }
};

/**
 * @method
 * @name keyword_onkeydown
 * @description 검색어 입력란에서 엔터키(keyCode 13) 입력 시 도움말 목록을 조회(listSync)한다.
 * @param {Object} e 키다운 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.keyword_onkeydown = function(e) {
    try {
        if (Number(e.keyCode) === 13) {
            scwin.listSync();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42040.keyword_onkeydown" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 검색조건(키워드·검색구분·시스템구분)으로 도움말 목록 조회 서브미션(sbm_dts_noticeList)을 실행하고 완료 콜백을 연결한다.
 * @returns {void}
 * @hidden N
 */
scwin.listSync = async function() {
    const KeyWord = keyword.value;

    const Condition1 = MxCombo_1.ValueOfIndex("VALUE", MxCombo_1.getSelectedIndex());
    const Condition2 = MxDataSet_code1.getCellData((cb_system_gbn.getSelectedIndex() + 1), "CD_VAL");
    url += "&SCREN_ID=" + "ULDSTF42040.gfm";
    url += "&keyword=" + KeyWord;
    url += "&Condition1=" + Condition1;
    url += "&Condition2=" + Condition2;
    const sbmOptions = {
        id : "sbm_dts_noticeList",
        action : "/scren.do",
        ref : "",
        target : "dts_noticeList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_noticeList_OnLoadCompleted(sbmRtn); // 구 콜백 연결

};

/**
 * @method
 * @name code1Sync
 * @description 시스템구분 코드 목록(MxDataSet_code1) 조회 서브미션(sbm_MxDataSet_code1)을 실행한다.
 * @returns {void}
 * @hidden N
 */
scwin.code1Sync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/scren.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setContnId
 * @description 신규("input") 상태가 아니면 선택 행의 화면ID(SCREN_ID)를 contnId에 보관한다.
 * @param {String} obj 행 인덱스 표현식(eval로 평가)
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    if (scwin.contnId !== "input") {
        scwin.contnId = dts_noticeList.getCellData(eval(obj), "SCREN_ID");
    }
};

/**
 * @method
 * @name getContnId
 * @description 보관된 화면ID(contnId)를 반환한다(도움말 상세 팝업에서 호출).
 * @returns {String} 보관된 화면ID(신규 시 "input")
 * @hidden N
 */
scwin.getContnId = function() {
    return scwin.contnId;
};

/**
 * @method
 * @name setSysCode
 * @description 선택 행의 시스템구분코드(NOTI_OBJ_SYS_TP_CD)를 notiObjSysCode에 보관한다.
 * @param {String} obj 행 인덱스 표현식(eval로 평가)
 * @returns {void}
 * @hidden N
 */
scwin.setSysCode = function(obj) {
    scwin.notiObjSysCode = dts_noticeList.getCellData(eval(obj), "NOTI_OBJ_SYS_TP_CD");
};

/**
 * @method
 * @name getSysCode
 * @description 보관된 시스템구분코드(notiObjSysCode)를 반환한다.
 * @returns {String} 보관된 시스템구분코드
 * @hidden N
 */
scwin.getSysCode = function() {
    return scwin.notiObjSysCode;
};

/**
 * @method
 * @name gform_onload
 * @description 구 gform onload — 도움말 목록(listSync)과 시스템구분 코드(MxDataSet_code1)를 초기 조회하고 시스템구분 콤보를 활성화한다.
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = async function() {
    scwin.listSync();
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    scwin.code1Sync();
    cb_system_gbn.Enable2 = true;
};
